#include <stdio.h>
double trung_binh(double a, double b, double c) {
    return (a + b + c) / 3.0;
}
int main(void) {
    double a, b, c;
    if (scanf("%lf %lf %lf", &a, &b, &c) != 3) return 1;
    printf("%.2f\n", trung_binh(a, b, c));
    return 0;
}
